import{_ as a,c as r,o as t,a2 as o}from"./chunks/framework.mqLGQ42V.js";const h=JSON.parse('{"title":"分组 (Groups) - Rive 编辑器","description":"基础概念 (Fundamentals) 使用分组来组织你的图形或增加额外的变换空间。","frontmatter":{"title":"分组 (Groups) - Rive 编辑器","description":"基础概念 (Fundamentals) 使用分组来组织你的图形或增加额外的变换空间。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 基础概念, 分组"}]]},"headers":[],"relativePath":"editor/fundamentals/groups.md","filePath":"editor/fundamentals/groups.md","lastUpdated":1774867914000}'),n={name:"editor/fundamentals/groups.md"};function s(d,e,i,p,c,l){return t(),r("div",null,[...e[0]||(e[0]=[o('<p>基础概念 (Fundamentals)</p><h1 id="分组-groups" tabindex="-1">分组 (Groups) <a class="header-anchor" href="#分组-groups" aria-label="Permalink to &quot;分组 (Groups)&quot;">​</a></h1><p>使用分组来组织你的图形或增加额外的变换空间。</p><p>按下快捷键 <code>G</code> 激活分组工具。点击画板上的任何位置即可添加一个新分组。然后，在层级面板 (Hierarchy) 中将对象拖放到该分组中。 你也可以在 macOS 中使用 <code>⌘</code>+<code>G</code> 或在 Windows 中使用 <code>Ctrl</code>+<code>G</code> 直接将选中的多个形状包裹进一个分组。 解除分组的快捷键在 macOS 中为 <code>⌘</code>+<code>Shift</code>+<code>G</code>，在 Windows 中为 <code>Ctrl</code>+<code>Shift</code>+<code>G</code>。</p><h2 id="​-分组样式-group-style" tabindex="-1"><a href="#group-style">​</a> 分组样式 (Group Style) <a class="header-anchor" href="#​-分组样式-group-style" aria-label="Permalink to &quot;[​](#group-style) 分组样式 (Group Style)&quot;">​</a></h2><p>分组的样式属性可以设置为“分组 (Group)”或“目标 (Target)”。</p><h3 id="​-分组-group" tabindex="-1"><a href="#group">​</a> 分组 (Group) <a class="header-anchor" href="#​-分组-group" aria-label="Permalink to &quot;[​](#group) 分组 (Group)&quot;">​</a></h3><p>“分组”是默认行为，其运作方式参考<a href="https://help.rive.app/editor/fundamentals/selecting-and-navigating-groups" target="_blank" rel="noreferrer">选择与导航分组 (Selecting and Navigating Groups)</a>。</p><h3 id="​-目标-target" tabindex="-1"><a href="#target">​</a> 目标 (Target) <a class="header-anchor" href="#​-目标-target" aria-label="Permalink to &quot;[​](#target) 目标 (Target)&quot;">​</a></h3><p>“目标”选项会在舞台上绘制一个始终可见的不同图标（通常分组只有在为空时才会显示图标）。当分组显示为“目标”时，它还会禁用<a href="https://help.rive.app/editor/fundamentals/selecting-and-navigating-groups" target="_blank" rel="noreferrer">选择与导航分组</a>章节中描述的功能。这意味着你可以直接点击选中该分组的任何子级对象（无需双击、按 Enter/Esc 或使用深层选择）。</p><blockquote><p><em>[原文档演示图由于官方服务器迁移已失效]</em> (描述: 分组切换为目标模式 GIF) “目标”选项在处理“约束 (Constraints)”时特别有用。</p></blockquote><h3 id="​-约束-constraints" tabindex="-1"><a href="#constraints">​</a> 约束 (Constraints) <a class="header-anchor" href="#​-约束-constraints" aria-label="Permalink to &quot;[​](#constraints) 约束 (Constraints)&quot;">​</a></h3><p><a href="/docs/editor/constraints/overview">约束是一种通过另一个目标对象来控制目标对象属性的方法。有些约束可以限制这些属性（及其层级关系），而另一些则可以将属性从一个对象复制到另一个对象。</a></p><p><a href="/docs/editor/fundamentals/procedural-shapes">程序化形状 (Procedural Shapes)</a><a href="https://help.rive.app/editor/fundamentals/selecting-and-navigating-groups" target="_blank" rel="noreferrer">选择与导航分组 (Selecting and Navigating Groups)</a></p>',14)])])}const g=a(n,[["render",s]]);export{h as __pageData,g as default};
